            page,
        }) => {
            const btn = page.locator(GLASS_BTN).first();
            if ((await btn.count()) === 0) test.skip();
            const box = await btn.boundingBox();
            if (!box) test.skip();
            if (!box) return;

            await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
            await pressDown(btn);
