                return {
                    plain: read('[data-slot="button"][data-variant="glass"]'),
                    hero: read('[data-slot="button"][data-variant="default"], [data-slot="button"][data-variant="primary-audacious"]'),
                };
            });
            const radius = (bf: string | null) => {
                const m = bf?.match(/blur\(([\d.]+)px\)/);
