    expect(
        meanAlpha,
        `the Speedtest preview swatch must read vivid (mean-alpha ${meanAlpha.toFixed(3)} ≥ 0.95), no longer the 0.259 dim outlier`,
    ).toBeGreaterThanOrEqual(0.95);
});

