                    const kids = pane.children;
                    return kids.length
                        ? (kids[kids.length - 1] as HTMLElement)
                        : null;
                };
                const wOf = () => dock.getBoundingClientRect().width;
                const tOf = () =>
                    parseFloat(
                        getComputedStyle(dock).getPropertyValue("--dock-morph-t"),
