        const risingWidth = countRising(tl.widths, 0.5);
        expect(
            risingWidth,
            `the dock-root box width rose over only ${risingWidth} rising frame(s) (< ${MIN_MORPH_FRAMES}) — the box SNAPPED / FROZE (W0=${tl.W0} W1=${tl.W1})`,
