        // (the dot field freezes mid-merge, the shape held + legible).
        const a = await readbackHash(page);
        await page.waitForTimeout(450);
        const b = await readbackHash(page);
        if (a !== "tainted" && a !== "no-canvas" && a.length > 64) {
            expect(a).toBe(b);
        }
    });
}

