const CHROMA_T = 28; // (max−min) over RGB ≥ this = a saturated blob pixel (both bgs are ~3)

function chroma(data: Buffer, i: number): number {
    const r = data[i]!;
    const g = data[i + 1]!;
    const b = data[i + 2]!;
    return Math.max(r, g, b) - Math.min(r, g, b);
