        let size = 0;
        stack.length = 0;
        stack.push(s);
        seen[s] = 1;
        while (stack.length) {
            const p = stack.pop()!;
            size++;
            const px = p % mw;
            const py = (p / mw) | 0;
            const nbrs = [
                px > 0 ? p - 1 : -1,
