            if ((await btn.count()) === 0) test.skip();
            const box = await btn.boundingBox();
            if (!box) test.skip();
            if (!box) return;

            const cx = box.x + box.width / 2;
            const cy = box.y + box.height / 2;
            const readT = () =>
                btn.evaluate((el) =>
                    parseFloat(
                        getComputedStyle(el as Element)
                            .getPropertyValue("--glass-btn-press-t")
                            .trim(),
                    ),
                );

